def comps(cells, H, W):
    seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if (r,c) in seen or not cells.get((r,c)): continue
            st=[(r,c)]; seen.add((r,c)); cc=[]
            while st:
                a,b=st.pop(); cc.append((a,b))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+da,b+db
                    if 0<=x<H and 0<=y<W and (x,y) not in seen and cells.get((x,y)):
                        seen.add((x,y)); st.append((x,y))
            out.append(cc)
    return out
