def nrm(p):
    mr=min(r for r,_ in p); mc=min(c for _,c in p)
    return sorted((r-mr,c-mc) for r,c in p)
def diheds(cells):
    pts=[(r,c) for r,c in cells]
    outs=[]
    base=[pts,[ (r,-c) for r,c in pts],[(-r,-c) for r,c in pts],[(-r,c) for r,c in pts]]
    for m,p in enumerate(base):
        for fl in range(2):
            q=[(c,r) for r,c in p] if fl else p
            q=[(r,-c) for r,c in p] if fl==1 else q
            if q not in outs and nrm(q) not in [nrm(x) for x in outs]: outs.append(nrm(q))
    uniq=[]
    seen=set()
    for x in outs:
        if x not in seen: seen.add(x); uniq.append(x)
    return uniq
