def comps_of(g, bg=None):
    seen=set();res=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if (bg is None or g[r][c]!=bg) and g[r][c]!=0 and (r,c) not in seen:
                col=g[r][c];dq=[(r,c)];seen.add((r,c));cells=[]
                while dq:
                    y,x=dq.pop();cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx]==col and (ny,nx) not in seen:
                            seen.add((ny,nx));dq.append((ny,nx))
                res.append((col,cells))
    return res
