        if r in seps:
            if cur is not None: bands.append(cur); cur=None
        else: cur=(r,) if cur is None else cur+(r,)
    if cur: bands.append(cur)
    # order components by topmost row (top->bottom reading)
    comps=[(col,normcells(cc)) for col,cc in raw if cc is not big and any(r<r0 or r>r1 or (c<c0 or c>c1) for r,c in cc)]
    comps.sort(key=lambda t:min(p[0] for p in t[1]))
    out=[[fc]*(c1-c0+1) for _ in range(r1-r0+1)]
    ok=True
    for bi,b in enumerate(bands):
        mark={(r-b[0],c-c0) for r in b for c in range(c0,c1+1) if g[r][c]==0}
        # allow diheds; prefer identity-first but must match; choose placement maximizing ... tie-break by preferring component whose norm equals mark exactly (no transform), else try diheds in fixed order: id, rot90, rot180, rot270, mirrors
        cand=[]
        for idx,(col,s) in enumerate(comps):
            for nm,f in [('id',lambda p:p),('rm',lambda p:(-p[0],p[1])),('cm',lambda p:(p[0],-p[1])),('rc',lambda p:(-p[0],-p[1])),
                          ('tr',lambda p:(p[1],p[0])),('tm',lambda p:(-p[1],p[0])),('ct',lambda p:(p[1],-p[0])),('cr',lambda p:(-p[1],-p[0]))]:
                v=[f((a,b_)) for a,b_ in s]
                hh=max(a for a,_ in v)+1; ww=max(b_ for _,b_ in v)+1
                for dr in range(-hh+1,b[-1]-b[0]+1):
                    for dx in range(-ww+1,c1-c0+1):
                        placed=frozenset((dr+a,dx+b_) for a,b_ in v)
                        if placed==mark: cand.append((idx,col,tuple(v),(dr,dx)))
        if len(set(h[:3] for h in cand if True and h[2])==set() and False): ok=False
        uniq={}
        for cand in cand: uniq.setdefault((cand[0],cand[1]),[]).append(cand[3])
        if len(uniq)!=1: ok=False
        (col,v),(dr,dx)=list(uniq.values())[0]
        for ar,ac_ in v:
            rr=b[0]+dr+ar; cc_=dx+ac_
            if 0<=rr<len(out) and 0<=cc_<len(out[0]): out[rr][cc_]=col
    return out,ok
