def dihedron_imgs(s):
    pts=list(s)
    imgs=[]
    for flip in [False,True]:
        for rot in range(4):
            p=[(r,c) for r,c in pts]
            for _ in range(rot): p=[(c,-r) for r,c in p]
            if flip: p=[(r,-c) for r,c in p]
            m=(min(a for a,_ in p),min(b for _,b in p))
            imgs.append(tuple(sorted((a-m[0],b-m[1]) for a,b in p)))
    return imgs
