from collections import Counter, deque
def comps(gi,c):
    seen=set(); res=[]
    for i,row in enumerate(gi):
        for j,v in enumerate(row):
            if v==c and (i,j) not in seen:
                q=[(i,j)];comp=[]
                while q:
                    y,x=q.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<len(gi) and 0<=nx<len(gi[0]) and gi[ny][nx]==c and (ny,nx) not in seen:
                            q.append((ny,nx))
                res.append(comp)
    return res
def norm(cs):
    y0=min(y for y,x in cs); x0=min(x for y,x in cs)
    return tuple(sorted((y-y0,x-x0) for y,x in cs))
def solve(gi):
    H,W=len(gi),len(gi[0])
    best=None
    for c in set(v for r in gi for v in r)-{0}:
        for cc in comps(gi,c):
            ys=[y for y,x in cc]; xs=[x for y,x in cc]
            y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
            border={(i,j) for i in range(y0,y1+1) for j in range(x0,x1+1) if i in(y0,y1) or j in(x0,x1)}
            miss=sum(1 for p in border if p not in set(cc))
            inner=[(i,j) for i in range(y0+1,y1) for j in range(x0+1,x1)]
            nz=sum(1 for p in inner if gi[p[0]][p[1]]==0)
            if nz>=4 and len(cc)>=border-miss and miss<=2:
                score=(nz*10+len(cc), -miss, -(y1-y0+x1-x0))
                if best is None or score>best[0]: best=(score,c,cc,(y0,y1,x0,x1))
    fc,frame,(y0,y1,x0,x1)=best[1],best[2],best[3]
    blocked=set(frame)
    outside_zeros=set(); dq=deque()
    for i in range(H):
        for j in range(W):
            if (i in(0,H-1) or j in(0,W-1)) and gi[i][j]==0 and (i,j) not in blocked:
                outside_zeros.add((i,j)); dq.append((i,j))
    while dq:
        y,x=dq.popleft()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and gi[ny][nx]==0 and (ny,nx) not in outside_zeros and (ny,nx) not in blocked:
                outside_zeros.add((ny,nx)); dq.append((ny,nx))
    zset={(i,j) for i in range(H) for j in range(W) if gi[i][j]==0 and (i,j) not in outside_zeros and (i,j) not in blocked}
    ocands=[];seen2=set()
    for i in range(H):
        for j in range(W):
            v=gi[i][j]
            if v!=fc and (i,j) not in seen2 and not(y0<=i<=y1 and x0<=j<=x1):
                q=[(i,j)];comp=[]
                while q:
                    yy,xx=q.pop()
                    if (yy,xx) in seen2: continue
                    seen2.add((yy,xx)); comp.append((yy,xx))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=yy+dy,xx+dx
                        if 0<=ny<H and 0<=nx<W and gi[ny][nx]==v and (ny,nx) not in seen2:
                            q.append((ny,nx))
                ocands.append(comp)
    colmap={norm(cc):gi[cc[0][0]][cc[0][1]] for cc in ocands}
    zb=[];seen=set()
    for p in sorted(zset):
        if p in seen: continue
        qq=[p];bb=[]
        while qq:
            yy,xx=qq.pop()
            if (yy,xx) in seen: continue
            seen.add((yy,xx)); bb.append((yy,xx))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=yy+dy,xx+dx
                if (ny,nx) in zset and (ny,nx) not in seen: qq.append((ny,nx))
        zb.append(bb)
    out=[[v for v in row] for row in gi]
    for z in zb:
        n=norm(z)
        assert n in colmap, (n,colmap,len(z))
        col=colmap[n]
        for y,x in z: out[y][x]=col
    return out,colmap,{tuple(sorted(c)):gi[c[0][0]][c[0][1]] for c in ocands}
for key in ['Demo pair 1','Demo pair 2']:
    o,cm,info=solve(G[key+' input'])
    print(key,'match',o==G[key+' output'],'outside:',info)

